issue_context.body:
When retry, r.ctx should be reset to original value.
```
......
for {
		url := r.URL().String()
		req, err := http.NewRequest(r.verb, url, r.body)
		if err != nil {
			return err
		}
                 // when retry, r.ctx should be reset to original value
		if r.timeout > 0 {
			if r.ctx == nil {
				r.ctx = context.Background()
			}
			var cancelFn context.CancelFunc
			r.ctx, cancelFn = context.WithTimeout(r.ctx, r.timeout)
			defer cancelFn()
		}
		if r.ctx != nil {
			req = req.WithContext(r.ctx)
		}
		req.Header = r.headers
                ......
```
Sample code to verify this bug:
```go
// test.go
package main

import (
	"context"
	"fmt"
	"time"
)

func main() {
	var ctx context.Context
	var cancel context.CancelFunc
	for i := 10; i > 0; i-- {
		if ctx == nil {
			ctx = context.Background()
		}
		// ctx = context.Background() // should reset ctx
		ctx, cancel = context.WithTimeout(ctx, time.Second)
		defer cancel()

		// do http request
		select {
		case <-ctx.Done():
			fmt.Println(ctx.Err())
		case <-time.After(time.Duration(i) * 200 * time.Millisecond): // simulate http request time cost
			// expect print OK!!! when i < 5
			fmt.Println("OK!!!")
		}
	}
}
```

